from target import newest_inspection_per_device


def test_largest_ts_wins():
    assert newest_inspection_per_device(
        [{"device": "d1", "ts": 1}, {"device": "d1", "ts": 9}], "device"
    ) == [{"device": "d1", "ts": 9}]


def test_tie_keeps_later_row():
    assert newest_inspection_per_device(
        [{"device": "d1", "ts": 5, "n": 1}, {"device": "d1", "ts": 5, "n": 2}], "device"
    ) == [{"device": "d1", "ts": 5, "n": 2}]


def test_empty_input_gives_empty_output():
    assert newest_inspection_per_device([], "device") == []
